INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block2', 'cyr', '¿Para qué sirve exactamente el bloque de Control ''Repetir hasta que < >'' en Scratch?', '[{"texto": "Repetir una acción continuamente, pero detenerse en el momento en el que se cumpla la condición del hexágono.", "correcta": true}, {"texto": "Esperar sin hacer nada hasta que ocurra la condición.", "correcta": false}, {"texto": "Repetir la acción infinitamente sin posibilidad de parar.", "correcta": false}, {"texto": "Hacer la acción una sola vez si se cumple la condición.", "correcta": false}]'::jsonb, '2', '2.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block2', 'cyr', '¿Cómo funciona el bloque condicional ''Si < > entonces''?', '[{"texto": "Se queda esperando infinitamente hasta que la condición se cumpla.", "correcta": false}, {"texto": "Ejecuta los bloques de su interior SOLO si la condición se cumple. Si no, se los salta.", "correcta": true}, {"texto": "Pregunta al usuario por teclado.", "correcta": false}, {"texto": "Repite la acción mientras la condición sea verdad.", "correcta": false}]'::jsonb, '2', '2.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block2', 'cyr', '¿Cómo funciona el bloque condicional ''Si < > entonces ... si no ...''?', '[{"texto": "Comprueba si hay dos condiciones verdaderas a la vez.", "correcta": false}, {"texto": "Repite el bucle dos veces.", "correcta": false}, {"texto": "Detiene el programa inmediatamente si hay un error.", "correcta": false}, {"texto": "Elige entre dos caminos: hace lo primero si se cumple, o hace lo segundo si es falso.", "correcta": true}]'::jsonb, '2', '2.1', 'alta');
