INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block2', 'cyr', 'El principio DRY en programación significa ''Don''t Repeat Yourself''. ¿Cómo lo aplicamos en Scratch?', '[{"texto": "Evitando jugar al mismo juego dos veces seguidas.", "correcta": false}, {"texto": "Creando ''Mis Bloques'' (Funciones) para reutilizar un trozo de código sin tener que copiarlo y pegarlo 20 veces.", "correcta": true}, {"texto": "Borrando el historial de navegación para no repetir búsquedas.", "correcta": false}, {"texto": "Usando siempre el bloque ''Por siempre'' para no cansarnos de hacer clic.", "correcta": false}]'::jsonb, '1', '1.3', 'alta');
