INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'En MakeCode, ¿cuál es la diferencia entre el bloque ''Al iniciar'' y el bloque ''Por siempre''?', '[{"texto": "Son exactamente lo mismo.", "correcta": false}, {"texto": "''Al iniciar'' sirve para apagar la placa y ''Por siempre'' para encenderla.", "correcta": false}, {"texto": "Ambos se ejecutan solo cuando pulsas el botón A.", "correcta": false}, {"texto": "''Al iniciar'' se ejecuta una sola vez al encender la placa; ''Por siempre'' repite su código infinitamente en bucle.", "correcta": true}]'::jsonb, '2', '2.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Si quieres que aparezca un corazón en la pantalla LED solo cuando aprietas el Botón A, ¿qué bloque usas?', '[{"texto": "El bloque Matemático: ''Escoger al azar''.", "correcta": false}, {"texto": "El bloque de inicio Básico: ''Al iniciar''.", "correcta": false}, {"texto": "El bloque de evento Rosa: ''Al presionarse el botón A''.", "correcta": true}, {"texto": "El bloque de bucle: ''Por siempre''.", "correcta": false}]'::jsonb, '2', '2.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'La Micro:bit tiene un/a Acelerómetro integrado/a. ¿Cuál es su función principal?', '[{"texto": "Mide la cantidad de luz que incide sobre la placa utilizando los propios LEDs de la pantalla como receptores.", "correcta": false}, {"texto": "Mide el calor ambiente estimando la temperatura del procesador interno de la placa.", "correcta": false}, {"texto": "Detecta si la placa se agita, se inclina, se cae o está boca abajo (detecta el movimiento y la gravedad).", "correcta": true}, {"texto": "Detecta los campos magnéticos y permite saber hacia dónde está el Norte.", "correcta": false}]'::jsonb, '1', '1.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
