INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', '¿Para qué sirve el módulo de Radio de la Micro:bit?', '[{"texto": "Para que dos o más placas se comuniquen entre sí de forma inalámbrica enviando mensajes.", "correcta": true}, {"texto": "Para recargar la batería de la placa a distancia.", "correcta": false}, {"texto": "Para escuchar las emisoras de radio FM de música.", "correcta": false}, {"texto": "Para conectarse a la red WiFi del instituto.", "correcta": false}]'::jsonb, '2', '2.1', 'baja');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Si quieres que dos placas Micro:bit hablen entre sí, ¿qué es lo primero que debes configurar al iniciar el programa?', '[{"texto": "No hay que hacer nada, se conectan solas a todas las placas del mundo.", "correcta": false}, {"texto": "Debes agitar las dos a la vez.", "correcta": false}, {"texto": "Debes poner ambas placas en el mismo ''Grupo de radio'' (ejemplo: Grupo 5).", "correcta": true}, {"texto": "Debes soldarles un cable entre ellas.", "correcta": false}]'::jsonb, '2', '2.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Si una placa emite un mensaje con ''Radio enviar cadena: "HOLA"'', ¿qué bloque debe usar la placa receptora para leerlo?', '[{"texto": "El bloque ''Mostrar cadena''.", "correcta": false}, {"texto": "El evento ''Al presionarse el botón A''.", "correcta": false}, {"texto": "El evento ''Al recibir radio receivedNumber''.", "correcta": false}, {"texto": "El evento ''Al recibir radio receivedString''.", "correcta": true}]'::jsonb, '2', '2.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', '¿Se puede cambiar el grupo de radio durante la ejecución de un programa en lugar de dejarlo fijo en ''Al iniciar''?', '[{"texto": "No, el grupo se graba a fuego y no se puede cambiar sin reiniciar.", "correcta": false}, {"texto": "No, el bloque de radio siempre pide un número fijo.", "correcta": false}, {"texto": "Sí, puedes asignar el bloque ''Radio establecer grupo'' a una Variable y cambiar el número con los botones.", "correcta": true}, {"texto": "Sí, pero solo en los modelos antiguos.", "correcta": false}]'::jsonb, '3', '3.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', '¿En qué principio mecánico se basa el coche Cutebot para moverse y girar?', '[{"texto": "En la Dirección por Cremallera, como un coche real con volante.", "correcta": false}, {"texto": "Se mueve volando con un ventilador.", "correcta": false}, {"texto": "En un solo motor que empuja todas las ruedas.", "correcta": false}, {"texto": "En la Conducción Diferencial: usa dos motores independientes (rueda izquierda y rueda derecha).", "correcta": true}]'::jsonb, '1', '1.4', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'En el Cutebot (conducción diferencial), si ponemos la rueda IZQUIERDA a velocidad 50 y la DERECHA a velocidad 50, ¿qué hará el robot?', '[{"texto": "Retrocederá en línea recta.", "correcta": false}, {"texto": "Girará a la derecha.", "correcta": false}, {"texto": "Girará a la izquierda.", "correcta": false}, {"texto": "Avanzará en línea recta hacia adelante.", "correcta": true}]'::jsonb, '1', '1.4', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'En el Cutebot, si ponemos la rueda IZQUIERDA a velocidad 50 y la DERECHA a 0 (quieta), ¿qué hará el robot?', '[{"texto": "Girará hacia la izquierda.", "correcta": false}, {"texto": "Avanzará en línea recta.", "correcta": false}, {"texto": "Girará hacia la derecha.", "correcta": true}, {"texto": "Se quedará bloqueado dando un error.", "correcta": false}]'::jsonb, '1', '1.4', 'alta');
