VALUES ('block3', 'cyr', '¿Cómo sabe un coche Siguelíneas por dónde tiene que ir?', '[{"texto": "Porque lo controlamos con un mando a distancia.", "correcta": false}, {"texto": "Gracias a dos pequeños sensores en la panza que disparan luz infrarroja para distinguir el color negro del blanco del suelo.", "correcta": true}, {"texto": "Utiliza un GPS para seguir una ruta.", "correcta": false}, {"texto": "Lleva una cámara 4K y una Inteligencia Artificial que procesa la carretera.", "correcta": false}]'::jsonb, '3', '3.1', 'baja');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Si montas un coche teledirigido usando dos Micro:bits, ¿cuál es el papel de cada placa?', '[{"texto": "Una es para reproducir música y la otra para mover las ruedas.", "correcta": false}, {"texto": "Una se usa como mando a distancia enviando señales por Radio, y la otra se pincha en el Cutebot para recibir las señales y mover los motores.", "correcta": true}, {"texto": "El Cutebot solo necesita una, la otra se tira a la basura.", "correcta": false}, {"texto": "Ambas se pinchan en el Cutebot para darle el doble de potencia.", "correcta": false}]'::jsonb, '3', '3.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Al escribir código en la web de MakeCode, hay un dibujo de una Micro:bit a la izquierda. ¿Para qué sirve?', '[{"texto": "Es un Simulador que ejecuta el código en tiempo real para que podamos probarlo (depurarlo) antes de pasarlo al robot físico.", "correcta": true}, {"texto": "Es una tienda para comprar componentes.", "correcta": false}, {"texto": "Sirve para jugar al tetris mientras te aburres.", "correcta": false}, {"texto": "Es solo un adorno estético.", "correcta": false}]'::jsonb, '2', '2.1', 'baja');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Cuando terminas tu programa en MakeCode y quieres pasarlo a tu placa física Micro:bit, ¿qué archivo debes descargar y copiar a la placa?', '[{"texto": "Un archivo con extensión .hex", "correcta": true}, {"texto": "Una foto .jpg", "correcta": false}, {"texto": "Un archivo .exe", "correcta": false}, {"texto": "Un documento .pdf", "correcta": false}]'::jsonb, '1', '1.1', 'media');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Para programar el coche Cutebot en MakeCode, no encuentras los bloques de los motores por defecto. ¿Qué tienes que hacer?', '[{"texto": "Tienes que escribir un correo a la empresa para que te los desbloqueen.", "correcta": false}, {"texto": "Tienes que programar los motores desde cero en lenguaje de máquina.", "correcta": false}, {"texto": "El Cutebot no se puede programar con MakeCode.", "correcta": false}, {"texto": "Debes ir a ''Extensiones'' e instalar la librería específica del Cutebot buscando su nombre.", "correcta": true}]'::jsonb, '2', '2.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Si durante el uso del simulador de MakeCode algo no hace lo que tú esperabas, ¿qué estás haciendo si observas el error, aíslas el bloque que falla y lo corriges?', '[{"texto": "Estás aplicando la ''Depuración'' (Debugging) para eliminar un Bug.", "correcta": true}, {"texto": "Estás hackeando la base de datos.", "correcta": false}, {"texto": "Estás haciendo un ataque Phishing.", "correcta": false}, {"texto": "Estás rompiendo el ordenador.", "correcta": false}]'::jsonb, '2', '2.1', 'media');
