INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', '¿Es correcto decir que el/la Fuente de Alimentación sirve para conectar y comunicar todos los componentes del ordenador entre sí.?', '[{"texto": "No, eso lo hace el ratón.", "correcta": false}, {"texto": "Depende del sistema operativo.", "correcta": false}, {"texto": "No, esa es la función de Placa Base (Motherboard).", "correcta": true}, {"texto": "Sí, es correcto.", "correcta": false}]'::jsonb, '1', '1.1', 'alta');
INSERT INTO topic_questions (topic_id, subject_id, enunciado, opciones, ce, criterio, dificultad)
VALUES ('block3', 'cyr', 'Según Isaac Asimov, ¿qué dice la Primera Ley de la robótica?', '[{"texto": "Un robot no puede causar daño a la humanidad ni, por inacción, permitir que la humanidad sufra daño.", "correcta": false}, {"texto": "Un robot debe proteger su propia existencia en la medida en que esta protección no entre en conflicto con la Primera o con la Segunda Ley.", "correcta": false}, {"texto": "Un robot no hará daño a un ser humano, ni por inacción permitirá que un ser humano sufra daño.", "correcta": true}, {"texto": "Un robot debe cumplir las órdenes dadas por los seres humanos, a excepción de aquellas que entren en conflicto con la Primera Ley.", "correcta": false}]'::jsonb, '1', '1.2', 'media');
